Replaced the two nibble-table steps with a single compile-time-generated 256-entry byte table, cutting each byte update to one lookup and one shift/XOR. This is faster because it halves the table lookups and shift/mask work per decoded byte.

```cpp
FIT_UINT16 CRC::Get16(FIT_UINT16 crc, FIT_UINT8 byte)
{
   static constexpr auto crc_table = [] {
      struct Table { FIT_UINT16 v[256]; };
      Table t{};
      for (int i = 0; i < 256; ++i)
      {
         FIT_UINT16 c = static_cast<FIT_UINT16>(i);
         for (int j = 0; j < 8; ++j)
         {
            c = static_cast<FIT_UINT16>((c & 1) ? ((c >> 1) ^ 0xA001) : (c >> 1));
         }
         t.v[i] = c;
      }
      return t;
   }();

   return static_cast<FIT_UINT16>((crc >> 8) ^ crc_table.v[(crc ^ byte) & 0xFF]);
}
```

